function examples(){return {risk:[{id:'r1',title:'Forklift Truck Operations',area:'Warehouse',reviewDate:'2027-01-15',person:'Alex Morgan (Example)',status:'Current'},{id:'r2',title:'BHS Corrugator Line',area:'Production',reviewDate:'2026-11-06',person:'Taylor Reed (Example)',status:'Due Soon'},{id:'r3',title:'Manual Handling',area:'Site-wide',reviewDate:'2026-09-30',person:'Jamie Smith (Example)',status:'Overdue'}],ssow:[{id:'s1',machine:'Mosca Strapper',reviewDate:'2027-03-15',person:'Alex Morgan (Example)',status:'Current',category:'Production',revision:'Rev 1.0'},{id:'s2',machine:'Paper Cutting Machine',reviewDate:'2026-11-12',person:'Taylor Reed (Example)',status:'In Review',category:'Production',revision:'Rev 0.2'},{id:'s3',machine:'Ducker Pallet Line',reviewDate:'2026-10-03',person:'Jamie Smith (Example)',status:'Overdue',category:'Warehouse',revision:'Rev 1.1'}],training:[],ppeStock:[],ppe:[{id:'p1',employee:'Sam Example',purchaseDate:'2026-10-12',amount:30,inspected:true,claimStatus:'Approved'},{id:'p2',employee:'Robin Example',purchaseDate:'2026-10-17',amount:24.5,inspected:false,claimStatus:'Pending'}],assets:suggestedAssets.map(a=>({...a})),incidents:[{id:'i1',date:'2026-10-21',type:'Near Miss',location:'Goods-in yard',description:'Pedestrian entered a marked vehicle route (fictional).',actions:'Refresh pedestrian route briefing and check barriers.',status:'Action Required'},{id:'i2',date:'2026-10-10',type:'Incident',location:'Production',description:'Minor slip with no injury (fictional).',actions:'Cleaned spill and reviewed inspection frequency.',status:'Closed'}]};}
const validSection=k=>Object.hasOwn(config,k);
function load(){try{const read=window.onboardDesktop.read();if(!read.ok)throw Error(read.error);const v=read.data;if(v&&typeof v==='object'&&['risk','ssow','ppe','incidents'].every(k=>Array.isArray(v[k]))){if(!Array.isArray(v.assets))v.assets=[];if(!Array.isArray(v.ppeStock))v.ppeStock=[];if(!Array.isArray(v.training))v.training=[];return v;}}catch(e){console.warn('Could not read saved records',e)}return examples()}
let db=load(),section='home',search='',filter='All';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dateFmt=v=>v?new Date(v+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';
const money=v=>new Intl.NumberFormat('en-GB',{style:'currency',currency:'GBP'}).format(Number(v)||0);
const labelStatus=v=>({good:['Current','Approved','Paid','Closed','In Service'].includes(v),warn:['Due Soon','In Progress','Draft','In Review','Pending','Investigating','Inspection Due','Under Maintenance','Unverified'].includes(v),bad:['Overdue','Rejected','Open','Action Required','Out of Service'].includes(v)});
function reviewPriority(date){if(!date)return 'No date';const today=new Date();today.setHours(0,0,0,0);const target=new Date(date+'T00:00:00');const days=Math.round((target-today)/86400000);return days<0?'Overdue review':days<=30?'Due in 30 days':'Up to date'}
function reviewPriorityHTML(date){const v=reviewPriority(date);return `<span class="status ${v==='Overdue review'?'bad':v==='Due in 30 days'?'warn':v==='Up to date'?'good':''}">${esc(v)}</span>`}
function ssowSummary(){const rows=db.ssow;const overdue=rows.filter(r=>reviewPriority(r.reviewDate)==='Overdue review').length;const soon=rows.filter(r=>reviewPriority(r.reviewDate)==='Due in 30 days').length;const drafts=rows.filter(r=>['Draft','In Review'].includes(r.status)).length;const missing=rows.filter(r=>!(r.attachments||[]).length).length;return `<div class="ssow-metrics"><div><b>${rows.length}</b><span>Total procedures</span></div><div><b>${overdue}</b><span>Overdue reviews</span></div><div><b>${soon}</b><span>Due in 30 days</span></div><div><b>${drafts}</b><span>Draft / in review</span></div><div><b>${missing}</b><span>Without document</span></div></div><p class="muted">Review priority is calculated automatically from the review date; workflow status remains editable. Review reminders appear when you open the dashboard, not as notifications.</p>`}
function assetManual(r){return (r.attachments||[]).find(a=>a.role==='Operating Manual')}
function assetSummary(){const rows=db.assets;const overdue=rows.filter(r=>r.inspectionDate&&reviewPriority(r.inspectionDate)==='Overdue review').length;const soon=rows.filter(r=>r.inspectionDate&&reviewPriority(r.inspectionDate)==='Due in 30 days').length;const noDocs=rows.filter(r=>!assetManual(r)).length;return `<div class="ssow-metrics asset-metrics"><div><b>${rows.length}</b><span>Total assets</span></div><div><b>${overdue}</b><span>Inspections overdue</span></div><div><b>${soon}</b><span>Due within 30 days</span></div><div><b>${rows.filter(r=>r.status==='Out of Service').length}</b><span>Out of service</span></div><div><b>${noDocs}</b><span>Missing operating manual</span></div></div><p class="muted">Suggested machines are examples; confirm each site asset and its manufacturer manual. Inspection dates are informational only. Confirm statutory examination requirements separately where applicable.</p>`}
function statusHTML(s){const t=labelStatus(s);return `<span class="status ${t.good?'good':t.bad?'bad':t.warn?'warn':''}">${esc(s)}</span>`}
function save(){try{const result=window.onboardDesktop.write(db);if(!result.ok)throw Error(result.error);return true}catch(e){alert('Unable to save to the desktop data file: '+e.message+' Export a backup and check free disk space.');return false}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.hidden=true,3000)}
function go(k){section=k;search='';filter='All';render()}
function render(){document.getElementById('nav').innerHTML=[['home','▦  Dashboard'],['risk','◈  Risk Assessments'],['ssow','▤  Safe Systems of Work'],['ppeStock','♧  PPE Inventory'],['ppe','£  Boot Claims'],['training','▤  Training Records'],['incidents','⚑  Incident Register'],['assets','▣  Asset Register']].map(([k,t])=>`<button type="button" class="${section===k?'active':''}" data-nav="${k}" aria-current="${section===k?'page':'false'}">${t}</button>`).join('');document.getElementById('page-title').textContent=section==='home'?'Health & Safety Dashboard':config[section].name;document.getElementById('page-subtitle').textContent=section==='home'?'A clear view of the safety records that matter.':config[section].subtitle;document.getElementById('content').innerHTML=section==='home'?homeHTML():registerHTML(section);document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>go(b.dataset.nav));document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>handleAction(b.dataset.action,b.dataset.section,b.dataset.id));if(section!=='home'){document.getElementById('search').oninput=e=>{search=e.target.value;updateRows()};document.getElementById('filter').onchange=e=>{filter=e.target.value;updateRows()}}}
function outstanding(){return db.risk.filter(r=>['Overdue','Due Soon','In Progress'].includes(r.status)).length+db.ssow.filter(r=>['Overdue','Due Soon','Draft','In Review'].includes(r.status)).length+db.incidents.filter(r=>r.status!=='Closed').length}
function homeHTML(){const counts=[['Risk Assessments',db.risk.length,'Assessment records','◈','risk'],['Safe Systems of Work',db.ssow.length,'Procedures recorded','▤','ssow'],['Outstanding Actions',outstanding(),'Items needing attention','!','incidents'],['Training Records',db.training.length,'Employee training evidence','▤','training'],['PPE Items',db.ppeStock.length,'Site PPE inventory','♧','ppeStock'],['Assets',db.assets.length,'Registered equipment','▣','assets']];const all=[...db.risk.map(r=>({name:r.title,kind:'Risk assessment',status:r.status,date:r.reviewDate})),...db.ssow.map(r=>({name:r.machine,kind:'SSOW',status:r.status,date:r.reviewDate})),...db.incidents.map(r=>({name:r.location,kind:r.type,status:r.status,date:r.date})),...db.assets.map(r=>({name:r.name,kind:'Asset',status:r.status,date:r.inspectionDate}))].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);return `<section class="home-hero"><div class="home-hero-copy"><span class="hero-tag">Onboard Corrugated</span><h2>Welcome to your Health &amp; Safety Dashboard</h2><p>Use this local dashboard to manage your Risk Assessments, Safe Systems of Work, PPE records, incident reports and equipment assets in one branded place. Review your records, attach supporting documents and keep your fictional example data organised while we continue shaping the system.</p></div><img src="data:image/jpeg;base64," alt="Onboard Corrugated logo" class="home-hero-logo"></section><div class="cards">${counts.map(([n,v,h,i,k])=>`<div class="card"><span class="icon">${i}</span><div class="label">${n}</div><div class="value">${v}</div><div class="hint">${h}</div><button type="button" class="btn small" style="margin-top:15px" data-nav="${k}">View register</button></div>`).join('')}</div><div class="overview-grid"><section class="panel"><div class="section-title"><h2>Recent activity</h2></div>${all.length?all.map(r=>`<div class="recent-item"><div><b>${esc(r.name)}</b><span class="muted">${esc(r.kind)} · ${dateFmt(r.date)}</span></div>${statusHTML(r.status)}</div>`).join(''):'<p class="empty">No records yet.</p>'}</section><section class="panel"><div class="section-title"><h2>Getting started</h2></div><div class="callout"><strong>Welcome to your local dashboard</strong>These records are fictional examples. Choose any register to add, edit or delete entries. Everything stays on this PC unless you export a backup. Small documents can be attached to individual records.</div><h2 style="margin:22px 0 13px">Backup &amp; data tools</h2><div class="utility"><button type="button" class="btn" data-action="export">⬇ Export backup</button><button type="button" class="btn" data-action="import">⬆ Import backup</button><button type="button" class="btn danger" data-action="reset">Reset to examples</button></div><p class="muted" style="margin-top:15px">Export regularly. Uninstalling and reinstalling normally retains saved records, but back up before updates or moving PCs. Backups include attachments; keep your own copies of all original documents. Open attached PDFs, images and text files directly. DOCX has a basic text preview; older DOC and Excel files still require their normal programs. Files must be under 15 MB each and total attachment storage is limited to 200 MB.</p></section></div>`}
function statusOptions(k){const field=k==='ppe'?'claimStatus':'status';const definition=config[k]?.fields.find(([name])=>name===field);return definition?.[4]||[]}
function registerHTML(k){return `${k==='ssow'?ssowSummary():k==='assets'?assetSummary():''}${k==='training'?'<div class="panel asset-guide"><h2>Employee training sheets</h2><p>Add an employee training record, then choose Files on the record to upload their completed training sheet, certificate, or attendance evidence. Training evidence is stored on this computer and included in exported backups. Verify refresher requirements against the relevant course and site procedures.</p></div>':''}${k==='ppeStock'?'<div class="panel asset-guide"><h2>Site PPE inventory</h2><p>Add each PPE product manually. Record stock, minimum quantity, specifications, storage location and optional issue information. Existing safety boot expense claims remain under Boot Claims.</p></div>':''}${k==='assets'?'<div class="panel asset-guide"><h2>Machine inventory and manuals</h2><p>Start with suggested equipment groups, then check actual machines, serial numbers and manufacturer documents on site. No manufacturer operating manuals are supplied in this prototype.</p><button type="button" class="btn primary" data-action="seedassets" data-section="assets">+ Add missing suggested machines</button></div>':''}<section class="panel"><div class="section-title"><h2>All ${esc(config[k].short)}</h2><button type="button" class="btn primary" data-action="add" data-section="${k}">+ Add record</button></div><div class="toolbar"><input id="search" class="field" type="search" placeholder="Search records…" value="${esc(search)}" aria-label="Search records"><select id="filter" class="field" aria-label="Filter by status"><option value="All">All statuses</option>${k==='assets'?['Missing operating manual','Overdue inspection','Inspection due in 30 days','No inspection date'].map(s=>`<option value="${esc(s)}" ${filter===s?'selected':''}>${esc(s)}</option>`).join(''):k==='ssow'?['Overdue review','Due in 30 days','Up to date','Missing document'].map(s=>`<option value="${esc(s)}" ${filter===s?'selected':''}>${esc(s)}</option>`).join(''):''}${statusOptions(k).map(s=>`<option value="${esc(s)}" ${filter===s?'selected':''}>${esc(s)}</option>`).join('')}</select><span id="record-count" class="muted"></span></div><div class="table-wrap"><table><thead><tr>${config[k].columns.map(c=>`<th>${esc(c[1])}</th>`).join('')}<th>Documents</th><th>Actions</th></tr></thead><tbody id="tbody"></tbody></table></div></section><p class="muted">Changes are saved automatically to your desktop data file. Use Export backup on the Dashboard for a copy.</p>`}
function cellHTML(k,field,r){let v=r[field];if(k==='assets'&&field==='name')return `<button type="button" class="asset-name-link" data-action="profile" data-section="assets" data-id="${esc(r.id)}">${esc(v)}</button>`;if(k==='ppeStock'&&field==='stock'){const n=Number(v),minimum=Number(r.minStock);return !Number.isFinite(n)?esc(v):n===0?'<span class="status bad">0 — Out of stock</span>':r.minStock!==''&&r.minStock!==undefined&&n<=minimum?`<span class="status warn">${n} — Low stock</span>`:esc(v)}if(field==='manualStatus')return assetManual(r)?'<span class="status good">Manual attached</span>':'<span class="status bad">Manual missing</span>';if(field==='reviewHealth')return reviewPriorityHTML(r.reviewDate);if(field==='reviewDate'||field==='purchaseDate'||field==='date'||field==='completedDate'||field==='expiryDate'||field==='inspectionDate')return dateFmt(v);if(field==='amount')return money(v);if(field==='inspected')return v?'<span class="status good">Yes — confirmed</span>':'<span class="status bad">No — not confirmed</span>';if(field==='status'||field==='claimStatus')return statusHTML(v);if(k==='training'&&field==='expiryDate')return r.expiryDate?reviewPriorityHTML(r.expiryDate):'<span class="muted">No expiry recorded</span>';if(field==='item')return `<strong>${esc(v)}</strong>`;if(field==='course')return `<strong>${esc(v)}</strong>`;if(field==='title'||field==='machine'||field==='employee'||field==='name')return `<strong>${esc(v)}</strong>`;if(field==='description')return `<span title="${esc(v)}">${esc(String(v).slice(0,92))}${String(v).length>92?'…':''}</span>`;return esc(v)}
