const MAX_FILE_BYTES=15*1024*1024,MAX_TOTAL_BYTES=200*1024*1024;
const allowedExtensions=/\.(pdf|doc|docx|xls|xlsx|jpg|jpeg|png|txt)$/i;
function bytesUsed(data=db){return Object.values(data).flat().flatMap(r=>r.attachments||[]).reduce((sum,a)=>sum+(a.size||0),0)}
function attachmentHTML(arr){return arr.length?arr.map((a,i)=>`<div class="attachment-item"><span>📄 <strong>${esc(a.name)}</strong> ${a.role==='Operating Manual'?'<span class="status good">Operating manual</span>':''} <span class="muted">(${Math.round(a.size/1024)} KB)</span></span><div class="attachment-controls"><button type="button" class="btn small primary" data-preview="${i}">Open</button><button type="button" class="btn small" data-download="${i}">Download</button><button type="button" class="btn small danger" data-remove="${i}">Remove</button></div></div>`).join(''):'<p class="muted">No documents attached yet.</p>'}
function downloadAttachment(a){const link=document.createElement('a');link.href=a.data;link.download=a.name;document.body.append(link);link.click();link.remove()}
